fn remove_odd_numbers(arr: &[i32]) -> Vec<i32> {
    // Create a new vector to hold the even numbers
    let mut evens = Vec::new();
    
    // Iterate over the input array
    for &num in arr {
        // Check if the number is even
        if num % 2 == 0 {
            // If it is even, push it to the evens vector
            evens.push(num);
        }
    }
    
    // Return the vector containing even numbers
    evens
}